function aggWinLossFilter(data) {
    let steplen = Math.ceil(data.length / 30);
    let step = 0;
    let result = [];
    let y = 0;
    for(let i = 0; i < data.length; i++){
        let d = data[i];
        y += d.y;
        step++;
        if (step == steplen || i == data.length - 1) {
            result.push({
                x: d.x,
                y: Math.round(100 * y / step) / 100,
                w: d.w,
                l: d.l
            });
            y = 0;
            step = 0;
        }
    }
    return result;
}
